/**
 * Inlined WASM binary for the POC so browser/Node/Jest all load without
 * relying on webpack asset URL emission or filesystem paths.
 * Regenerate after rebuilding the WASM: node scripts are in wasm/build.sh notes.
 */
export const YARA_WASM_BASE64 =
  '';

export const loadYaraWasmBinary = (): ArrayBuffer => {
  const binary = atob(YARA_WASM_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
};
